import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: string;
}

const themes: { value: ThemeValue; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const fonts = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces' },
  { value: 'mono', label: 'JetBrains Mono' },
];

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: defaultValue?.theme ?? 'system',
    scale: defaultValue?.scale ?? 100,
    dense: defaultValue?.dense ?? false,
    font: defaultValue?.font ?? 'sans',
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel = themes.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section style={{ display: 'grid', gap: '20px', maxWidth: '520px' }}>
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <JxToggle
        items={themes}
        value={settings.theme}
        onValueChange={(value) => update({ theme: value as ThemeValue })}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={fonts}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

